"use strict";

const fs = require("fs");

exports.summarize = function summarize() {
  const own = require("./package.json");
  const leafPath = require.resolve("pm-metadata-leaf/package.json");
  const leaf = JSON.parse(fs.readFileSync(leafPath, "utf8"));
  return `pmmeta:${own.name}:${leaf.name}:${leaf.version}`;
};
